#include <bits/stdc++.h>
using namespace std;

string normalize_email() {
    string email_input;
    cin >> email_input;
    size_t at_location = email_input.find("at", 1);
    if (at_location != string::npos) {
        email_input.replace(at_location, 2, "@");
    }
    size_t dot_location = email_input.find("dot", 1);
    while (dot_location != string::npos && email_input.size() != dot_location + 3) {
        email_input.replace(dot_location, 3, ".");
        dot_location = email_input.find("dot", 1);
    }
    return email_input;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    string email;
    cin >> email;
    cout << normalize_email() << "\n";
    return 0;
}
